//! SRD-85 bundled-workload catalog assembly.
//!
//! The whole manifest is generated by this crate's `build.rs` —
//! the binary is the only catalog assembler, so it is also the
//! only generator. Adapter workload sets are included there
//! behind the same feature gates that compile the adapters in,
//! keeping the catalog truthful about what this binary can run.
//! [`install_catalog`] runs once at startup, before any
//! workload resolution.

include!(concat!(env!("OUT_DIR"), "/bundled_workloads.rs"));

/// Install the process-wide catalog.
pub fn install_catalog() {
    nmbrs_workload::catalog::install(&[BUNDLED]);
}
